// src/engine/version.ts
var ENGINE_VERSION = "1.0.1-wip.16";
var DATA_VERSION = "1.1-wip.16";
var defined = (get, fallback) => {
  try {
    return get();
  } catch {
    return fallback;
  }
};
var ENGINE_HASH = defined(() => __ENGINE_HASH__, "dev");
var DATA_HASH = defined(() => __DATA_HASH__, "dev");
var VERSION_LOCKED = defined(() => __VERSION_LOCKED__, false);
var LOCKED_ON = defined(() => __LOCKED_ON__, "");
var softwareStamp = () => ({
  engine: ENGINE_VERSION,
  engineHash: ENGINE_HASH,
  data: DATA_VERSION,
  dataHash: DATA_HASH,
  locked: VERSION_LOCKED
});
function stampDifferences(saved, now = softwareStamp()) {
  if (!saved)
    return [];
  const out = [];
  if (saved.engine !== now.engine || saved.engineHash !== now.engineHash)
    out.push(`engine ${saved.engine} (${saved.engineHash}) when saved; this build is ${now.engine} (${now.engineHash})`);
  if (saved.data !== now.data || saved.dataHash !== now.dataHash)
    out.push(`data library v${saved.data} (${saved.dataHash}) when saved; this build is v${now.data} (${now.dataHash})`);
  return out;
}

