// src/engine/core/loads.ts
var LOAD_TYPES = ["D", "L", "Lr", "S", "W", "E"];
var zeroLoads = () => ({ D: 0, L: 0, Lr: 0, S: 0, W: 0, E: 0 });
function addLoads(a, b, k = 1) {
  const out = zeroLoads();
  for (const t of LOAD_TYPES)
    out[t] = a[t] + k * b[t];
  return out;
}
function scaleLoads(a, k) {
  const out = zeroLoads();
  for (const t of LOAD_TYPES)
    out[t] = a[t] * k;
  return out;
}
var loadVector = (partial) => ({ ...zeroLoads(), ...partial });

