// src/engine/core/fmt.ts
function fmt(v, d = 2) {
  if (!Number.isFinite(v))
    return "—";
  return v.toLocaleString("en-US", { minimumFractionDigits: d, maximumFractionDigits: d });
}
function fmtInFraction(inches, denom = 16) {
  if (!Number.isFinite(inches))
    return "—";
  const sign = inches < 0 ? "-" : "";
  const total = Math.round(Math.abs(inches) * denom);
  const whole = Math.floor(total / denom);
  let num = total % denom;
  let den = denom;
  while (num && num % 2 === 0 && den % 2 === 0) {
    num /= 2;
    den /= 2;
  }
  if (!num)
    return `${sign}${whole}`;
  return whole ? `${sign}${whole}-${num}/${den}` : `${sign}${num}/${den}`;
}
function fmtFtIn(ft) {
  if (!Number.isFinite(ft))
    return "—";
  const sign = ft < 0 ? "-" : "";
  let f = Math.floor(Math.abs(ft));
  let inch = (Math.abs(ft) - f) * 12;
  if (inch > 11.97) {
    f += 1;
    inch = 0;
  }
  return `${sign}${f}′-${fmtInFraction(inch)}″`;
}

