      storyId: s.id,
      name: s.name,
      hx: hx[i],
      w: row.w,
      Fx: row.Fx,
      VE: row.Vx,
      windF: { X: bx.F, Y: by.F },
      VW: { X: 0, Y: 0 },
      windBands: { X: bx, Y: by },
      Fpx,
      FpxCalc,
      FpxMin,
      FpxMax
