    id: r.id,
    mark: r.mark,
    kind: "rafter",
    title: "Rafter",
    callout: `${r.size} ${r.species} ${r.grade} @ ${fmt(r.spacing, r.spacing % 1 ? 1 : 0)} in. o.c.`,
    pass: ev.pass,
    governing: ev.governing,
    checks: ev.checks,
    reactions,
    loadLines: b.lines,
    assumptions,
    flags,
    alternatives,
    input: r,
    design,
