var TRANSIENT2 = ["L", "Lr", "S"];
function shearDeflection(a, c, K) {
  const nodeAt = (x) => {
    let best = 0;
    for (let i = 1;i < a.x.length; i++)
      if (Math.abs(a.x[i] - x) < Math.abs(a.x[best] - x))
        best = i;
    return best;
  };
  const out = new Array(a.x.length).fill(0);
  const g = a.geometry;
  a.segments.forEach(([s, e], k) => {
    const isLeftCant = k === 0 && g.leftCantilever > 0;
    const isRightCant = k === a.segments.length - 1 && g.rightCantilever > 0;
    const Ms = c.M[nodeAt(s)];
    const Me = c.M[nodeAt(e)];
    for (let i = 0;i < a.x.length; i++) {
      const x = a.x[i];
      if (x < s - 0.000000001 || x > e + 0.000000001)
        continue;
      let chord;
      if (isLeftCant)
        chord = Me;
      else if (isRightCant)
        chord = Ms;
      else
        chord = Ms + (Me - Ms) * (x - s) / (e - s);
      out[i] = 8 * (c.M[i] - chord) * 12 / K;
    }
  });
  return out;
}
