    governing,
    checks,
    reactions: [],
    loadLines: lines,
    assumptions,
    flags,
    input: s,
    demand: dem,
    sides,
    vsc,
    vwc,
    windSum,
    asdS,
    comboRule,
    Gac,
    aspect,
    maxAspect,
    Car,
    vAllowS,
    vAllowW,
    vS,
    vW,
    selfPlf,
