// src/engine/members/truss.ts
function designTruss(ctx, t) {
  if (!t.bearings.length)
    throw new Error("Enter at least one truss bearing reaction");
  const nds = ndsOf(ctx);
  const plate = lumberData(t.plate.species, t.plate.grade, t.plate.size, nds);
  const plateWidth = Number(t.plate.size.split("x")[1]) <= 4 ? 3.5 : Number(t.plate.size.split("x")[1]) === 6 ? 5.5 : 7.25;
  const vec = (b) => loadVector({ D: b.D, L: b.L, Lr: b.Lr, S: b.S, W: b.W });
  const present = { D: true };
  for (const b of t.bearings)
    for (const k of LOAD_TYPES)
      if (Math.abs(vec(b)[k]) > 0.000000001)
        present[k] = true;
  const combos = relevantCombinations(asdCombinations({ asce7: asce7Of(ctx), SDS: ctx.SDS, includeWind: !!present.W }), present);
  const lines = [];
  const checks = [];
  const bearingChecks = [];
  const reactions = t.bearings.map((b, i) => {
    const v = vec(b);
    for (const k of LOAD_TYPES)
      if (Math.abs(v[k]) > 0.000000001)
        lines.push({
          type: k,
          label: `Bearing ${b.name} — truss reaction (truss design drawings)`,
          expr: `${fmt(v[k], 0)} lb per ${t.girder ? "girder" : "truss"}`,
          value: v[k],
          unit: "lb"
        });
    let maxDown = -Infinity;
    let maxDownCombo = "";
    let minNet = Infinity;
    let minNetCombo = "";
    for (const c of combos) {
      const x = combine(v, c);
      if (x > maxDown) {
        maxDown = x;
        maxDownCombo = c.label;
      }
      if (x < minNet) {
        minNet = x;
        minNetCombo = c.label;
      }
    }
    const lb = b.width;
    const Cb = bearingAreaFactor(lb, false);
    const A = lb * plateWidth;
    const fcperp = maxDown / A;
    const Fprime = plate.ref.Fcperp * Cb;
    bearingChecks.push({
      name: b.name,
      R: maxDown,
      combo: maxDownCombo,
      lb,
      Cb,
      A,
      fcperp,
      Fprime,
      ratio: fcperp / Fprime
    });
    checks.push({
      name: `Bearing ${b.name} on ${t.plate.size} plate (NDS 3.10.2)`,
      demand: fcperp,
      capacity: Fprime,
      ratio: fcperp / Fprime,
      pass: fcperp <= Fprime,
      combo: maxDownCombo,
      CD: 1,
      unit: "psi"
    });
    const perFoot = !t.girder && t.spacing > 0 ? loadVector(Object.fromEntries(LOAD_TYPES.map((k) => [k, v[k] * 12 / t.spacing]))) : undefined;
    return { support: i, name: b.name, x: b.x, byType: v, perFoot, maxDown, maxDownCombo, minNet, minNetCombo };
  });
  const flags = [
    "Trusses designed by the truss manufacturer (deferred submittal); reactions above are taken from the truss design drawings and must be updated when the final truss design is received"
  ];
  if (reactions.some((r) => r.minNet < -1))
    flags.push("Net uplift at truss bearings — tie each truss to the plate; see connector schedule");
  return {
    id: t.id,
    mark: t.mark,
    kind: "truss",
    title: t.girder ? "Girder truss (imported)" : "Roof truss (imported)",
    callout: t.girder ? `${t.plies}-ply girder truss, ${fmt(t.span, 2)} ft span` : `Trusses @ ${fmt(t.spacing, t.spacing % 1 ? 1 : 0)} in. o.c., ${fmt(t.span, 2)} ft span`,
    pass: checks.every((c) => c.pass),
    governing: governingCheck(checks),
    checks,
    reactions,
    loadLines: lines,
    assumptions: [
      fromDefault("Truss reactions", `Entered from ${t.designRef || "the truss design drawings"}`, "truss manufacturer", !t.designRef),
      fromDefault("Plate bearing", "Truss bearing checked on the top plate only; truss chord bearing by the truss designer", "NDS 3.10.2")
    ],
    flags,
    input: t,
    bearingChecks
  };
}

