  assumptions.push(fromDefault("Rigid footing", "Wall and footing act as one rigid body; linear soil pressure, no tension", "engineer"), fromDefault("Allowable soil pressure", `${fmt(f.qa, 0)} psf — ${f.qaSource}`, f.qaSource, true), fromDefault("Sliding resistance", `${f.friction !== undefined ? `friction μ = ${fmt(f.friction, 2)}` : `cohesion ${fmt(f.cohesion ?? 0, 0)} psf`}; lateral bearing ${fmt(f.lateralBearing, 0)} psf/ft on one end face`, f.soilSource, true), fromDefault("Uplift length", "Hold-down uplift spread over the footing length needed to mobilise 0.9 × the dead weight per foot; that length checked as a cantilever (M_u = T_u L_e / 2)", "engineer"));
