    governing: governingCheck(checks),
    checks,
    reactions: [],
    loadLines: lines,
    assumptions,
    flags,
    input: f,
    wallMark: w.mark,
    arm,
    weights: { wall: wallSelf, footing: wFtg, stem: wStem, soil: wSoil, extra },
