  const psiEdN = i.ca1 >= 1.5 * i.hef ? 1 : 0.7 + 0.3 * i.ca1 / (1.5 * i.hef);
  const kc = i.cracked ? p.kcCr : p.kcUncr;
  const Nb = kc * lam * Math.sqrt(i.fc) * i.hef ** 1.5;
  const cac = p.cac ?? 2 * i.hef;
