    futa,
    Nsa,
    phiNsa,
    ANc,
    ANco,
    psiEdN,
    kc,
    Nb,
    Ncb,
    phiNcb,
    tau,
    cNa,
    ANa,
    ANao,
    psiEdNa,
    Nba,
    Na,
    phiNa,
    seismicFactor: sf,
    phiNn: tGov[1],
    tGov: tGov[0],
    Vsa,
    phiVsa,
    le,
    Vb,
    AVc,
    AVco,
    psiH,
    Vcb,
    phiVcb,
    Vcp,
    phiVcp,
    phiVn: vGov[1],
    vGov: vGov[0]
