  const Pc = lrfd ? 0.65 * Pp : Pp / 2.31;
  const X = P > 0 ? Math.min(1, 4 * d * bf / (d + bf) ** 2 * (P / Pc)) : 0;
  const lam = X > 0 ? Math.min(1, 2 * Math.sqrt(X) / (1 + Math.sqrt(1 - X))) : 0;
  const lambdaN = lam * Math.sqrt(d * bf) / 4;
  const l = Math.max(m, n, lambdaN);
  const f = i.N / 2 - i.rod.e1;
  let e = 0;
  let ecrit = i.N / 2;
  let regime = "axial";
  let Y = i.N;
  let q = 0;
  let T = 0;
  if (P <= 0) {
    regime = "uplift";
    T = -P + (Math.abs(F.M) > 0 ? Math.abs(F.M) / (2 * f) : 0);
    Y = 0;
  } else {
    e = Math.abs(F.M) / P;
    ecrit = i.N / 2 - P / (2 * qMax);
    if (e <= 0.000000001) {
      regime = "axial";
      Y = i.N;
      q = P / i.N;
    } else if (e <= ecrit) {
      regime = "small";
      Y = i.N - 2 * e;
      q = P / Y;
    } else {
      regime = "large";
      const a = f + i.N / 2;
      const disc = a * a - 2 * P * (e + f) / qMax;
      if (disc < 0)
        throw new Error("Base plate: no real bearing length — increase the plate size (DG1 Eq. 3.4.4)");
      Y = a - Math.sqrt(disc);
      q = qMax;
      T = qMax * Y - P;
    }
  }
