  const tReqTension = T > 0 ? lrfd ? Math.sqrt(4 * T * x / (phiB * i.B * i.Fy)) : Math.sqrt(4 * T * x * omB / (i.B * i.Fy)) : 0;
  const tReq = Math.max(tReqBearing, tReqTension);
  const Trod = T / Math.max(1, i.rod.nTension);
  lines.push(`A1 = B N = ${A1.toFixed(1)} in²; A2 = ${i.A2.toFixed(0)} in²; P_p = 0.85 f'c A1 min(√(A2/A1), 2) = ${Pp.toFixed(1)} kip (J8-2)`, `f_p,max = ${lrfd ? "φ_c" : "1/Ω_c ×"} 0.85 f'c min(√(A2/A1), 2) = ${fpMax.toFixed(2)} ksi; q_max = f_p,max B = ${qMax.toFixed(2)} kip/in`, `m = (N − ${kd.toFixed(2)}d)/2 = ${m.toFixed(3)} in; n = (B − ${kb.toFixed(2)}${round ? "D" : "b_f"})/2 = ${n.toFixed(3)} in; λn' = ${lambdaN.toFixed(3)} in; l = ${l.toFixed(3)} in`);
  const Ab = Math.PI * i.rod.d ** 2 / 4;
  const fv = F.V / (Math.max(1, i.rod.nShear) * Ab);
  const z = i.rod.groutPad ? i.tp + i.rod.washer / 2 : 0;
  const Ml = F.V * z / Math.max(1, i.rod.nShear);
  const Zr = i.rod.d ** 3 / 6;
