  const rodRatio = Math.max(FntPrime > 0 ? ft / FntPrime : Infinity, fv / fvCap);
  const w = i.weld.w;
  const Aw = hss ? 2 * (d + bf) : 2 * bf + 2 * (d - 2 * i.col.tf);
  const Sw = hss ? d * bf + d * d / 3 : bf * d + d * d / 3;
