    id: u.id,
    mark: u.mark,
    kind: "uplift",
    title: "Wind uplift load path",
    callout: rows.map((r) => r.model).join(" → "),
    pass: checks.every((c) => c.pass),
    governing: governingCheck(checks),
    checks,
    reactions: [],
    loadLines: lines,
    assumptions,
    flags,
    input: u,
    rows,
    W,
    Dsrc
