    report.converted.push(`${where(sec, e)}: ${e.key}: ${e.raw} → ${got.links.map((l) => `${l.label} (${l.kind}${l.factor !== 1 ? ` × ${l.factor}` : ""})`).join("; ")}`);
    report.applied++;
