// src/components/report/package.ts
function packageChecks(p, design) {
  const dup = duplicateMarks(p);
  const outcomes = [...design.outcomes.values()];
  const errors = outcomes.filter((o) => o.error);
  const fails = outcomes.filter((o) => o.result && !o.result.pass);
  const verify = outcomes.reduce((n, o) => n + (o.result ? o.result.assumptions.filter((a) => a.verify).length : 0), 0);
  const carried = new Set([
    ...p.members.flatMap((m) => m.links.map((l) => `${l.sourceId}:${l.support}`)),
    ...p.members.flatMap((m) => m.kind === "basePlate" && m.sourceId ? [`${m.sourceId}:0`, `${m.sourceId}:1`] : [])
  ]);
  const tied = new Set(p.members.flatMap((m) => m.kind === "connector" || m.kind === "uplift" ? [`${m.sourceId}:${m.support}`] : []));
  const uncarried = [];
  const untied = [];
  for (const o of outcomes) {
    if (!o.result)
      continue;
    o.result.reactions.forEach((r, i) => {
      if (o.result.kind === "rafter" && o.result.input.ridge === "board" && i === 1)
        return;
      if (o.result.kind === "ledger")
        return;
      if (r.maxDown > 1 && !carried.has(`${o.spec.id}:${i}`))
        uncarried.push(`${o.result.mark} ${r.name}`);
      if (r.minNet < -1 && !tied.has(`${o.spec.id}:${i}`))
        untied.push(`${o.result.mark} ${r.name}`);
    });
  }
  const out = [
    { ok: dup.length === 0, text: dup.length ? `Duplicate marks: ${dup.join(", ")}` : "Member marks are unique" },
    {
      ok: errors.length === 0,
      text: errors.length ? `Members with errors: ${errors.map((e) => e.spec.mark).join(", ")}` : "Every member designed without error"
    },
    {
      ok: fails.length === 0,
      text: fails.length ? `Members failing: ${fails.map((e) => e.spec.mark).join(", ")}` : "Every member passes all checks"
    },
    {
      ok: verify === 0,
      verifyItems: true,
      text: verify ? `${verify} item(s) marked VERIFY — resolve before the package is issued` : "No VERIFY items"
    },
    {
      ok: uncarried.length === 0,
      text: uncarried.length ? `Reactions not yet carried to a supporting member or footing: ${uncarried.join(", ")}` : "Every reaction is carried down to a supporting member or footing"
    },
    {
      ok: untied.length === 0,
      text: untied.length ? `Net uplift without a connector: ${untied.join(", ")}` : "Every net uplift reaction has a connector"
    }
  ];
  if (p.lateral?.enabled) {
    if (design.lateralError)
      out.push({ ok: false, text: `Lateral analysis: ${design.lateralError}` });
    for (const w of design.lateral?.warnings ?? [])
      out.push({ ok: false, text: `Lateral: ${w}` });
    const lines = design.lateral?.lines ?? [];
    const empty = lines.filter((l) => !p.members.some((m) => m.kind === "shearWall" && m.lineId === l.line.id));
    out.push({
      ok: empty.length === 0,
      text: empty.length ? `Wall lines without shear walls: ${empty.map((l) => l.line.name).join(", ")}` : "Every wall line has at least one shear wall"
    });
    const missing = [];
    for (const st of p.lateral.stories)
      for (const dir of ["X", "Y"])
        if (p.lateral.lines.some((l) => l.storyId === st.id && l.dir === dir) && !p.members.some((m) => m.kind === "diaphragm" && m.storyId === st.id && m.dir === dir))
          missing.push(`${st.name} ${dir}`);
    out.push({
      ok: missing.length === 0,
      text: missing.length ? `Diaphragm not designed for: ${missing.join(", ")}` : "Diaphragm, chords and collectors designed for every story and direction"
    });
  }
  return out;
}
var r32 = (x) => String(Math.round(x * 1000) / 1000);
function validationItems(p, design) {
  const out = packageChecks(p, design).filter((c) => !c.ok).map((c) => ({ where: "Package", text: c.text }));
  if (design.circular.length)
    out.push({
      where: "Package",
      text: `Circular load path: ${design.circular.map((id) => p.members.find((m) => m.id === id)?.mark ?? id).join(", ")}`
    });
  for (const m of p.members) {
    const o = design.outcomes.get(m.id);
    const at = (text) => out.push({ where: m.mark, memberId: m.id, text });
    if (!o)
      continue;
    if (o.error) {
      at(`Error: ${o.error}`);
      continue;
    }
    const r = o.result;
    if (!r)
      continue;
    for (const c of r.checks)
      if (!c.pass)
        at(`FAIL — ${c.name}: ${r32(c.demand)} / ${r32(c.capacity)} ${c.unit} = D/C ${r32(c.ratio)} (${c.combo})`);
    for (const f of r.flags)
      if (/REQUIRED INPUT|VERIFY/.test(f))
        at(f);
    for (const a of r.assumptions)
      if (a.verify)
        at(`VERIFY — ${a.item}: ${a.value}`);
  }
  return out;
}

// mcp/server.ts
var EXAMPLES = {
  new: () => newProject(),
  example: exampleProject,
  sanMiguel: sanMiguelProject,
  eastLincoln: eastLincolnTrussProject,
  deck: deckExampleProject
};
var project = exampleProject();
var filePath;
var ok = (data) => ({ content: [{ type: "text", text: JSON.stringify(data, null, 2) }] });
var fail = (msg) => ({ content: [{ type: "text", text: msg }], isError: true });
function merge2(base, patch) {
  if (patch === null)
    return;
  if (typeof patch !== "object" || Array.isArray(patch) || typeof base !== "object" || base === null || Array.isArray(base))
    return patch;
  const out = { ...base };
  for (const [k, v] of Object.entries(patch)) {
    const m = merge2(out[k], v);
    if (m === undefined)
      delete out[k];
    else
      out[k] = m;
  }
  return out;
}
function commit(candidate) {
  const r = projectSchema.safeParse(candidate);
  if (!r.success)
    return r.error.issues.slice(0, 10).map((i) => `${i.path.join(".") || "(root)"}: ${i.message}`);
  project = r.data;
  return;
}
function findMember(key) {
  return project.members.find((m) => m.id === key) ?? project.members.find((m) => m.mark.toLowerCase() === key.toLowerCase());
}
var r33 = (x) => Math.round(x * 1000) / 1000;
function memberRows() {
  const d = designProject(project);
  return {
    d,
    rows: project.members.map((m) => {
      const o = d.outcomes.get(m.id);
      const res = o?.result;
      return {
        id: m.id,
        mark: m.mark,
        kind: m.kind,
        level: "levelId" in m ? m.levelId : undefined,
        callout: res?.callout,
        status: o?.error ? "ERROR" : !res ? "NOT DESIGNED" : res.pass ? "OK" : "FAIL",
        governing: res ? `${res.governing.name}: D/C = ${r33(res.governing.ratio)} (${res.governing.combo})` : undefined,
        error: o?.error
      };
    })
  };
}
var server = new McpServer({ name: "housecalc", version: "1.0.0" });
function tool(name, config, handler) {
  const register = server.registerTool.bind(server);
  register(name, config, handler);
}
tool("load_project", {
  description: "Open a HouseCalc project: a *.housecalc.json file (path) or a built-in project (example: new | example | sanMiguel | eastLincoln | deck). Replaces the project in memory.",
  inputSchema: {
    path: stringType2().optional(),
    example: enumType2(["new", "example", "sanMiguel", "eastLincoln", "deck"]).optional()
  }
}, async ({ path, example }) => {
  if (path) {
    const r = parseProject(await readFile(resolve(path), "utf8"));
    if (!r.ok)
      return fail(`Not a valid HouseCalc project:
${r.errors.join(`
`)}`);
    project = r.project;
    filePath = resolve(path);
    return ok({ loaded: filePath, warnings: r.warnings, members: project.members.length });
  }
  project = EXAMPLES[example ?? "new"]();
  filePath = undefined;
  return ok({ loaded: example ?? "new", members: project.members.length });
});
tool("save_project", {
  description: "Write the project in memory to a *.housecalc.json file (default: the file it was opened from). Open it in the HouseCalc app to print the PDF/DOCX package.",
  inputSchema: { path: stringType2().optional() }
}, async ({ path }) => {
  const target = path ? resolve(path) : filePath;
  if (!target)
    return fail("No file path — pass path (e.g. ./my-job.housecalc.json).");
  await writeFile(target, serializeProject(project));
  filePath = target;
  return ok({ saved: target });
});
tool("project_summary", {
  description: "Project info, criteria, structures/levels, marks and every member with its callout, status and governing D/C.",
  inputSchema: {}
}, async () => {
  const { rows } = memberRows();
  return ok({
    file: filePath,
    info: project.info,
    criteria: project.criteria,
    structures: project.structures,
    marks: project.marks,
    assemblies: project.assemblies.map((a) => ({ id: a.id, name: a.name })),
    members: rows
  });
});
tool("get_member", {
  description: "Full input spec of one member (by id or mark) plus its design result: callout, governing check, all checks, reactions, flags, assumptions (verify items flagged).",
  inputSchema: { member: stringType2() }
}, async ({ member }) => {
  const m = findMember(member);
  if (!m)
    return fail(`No member '${member}'.`);
  const o = designProject(project).outcomes.get(m.id);
  const res = o?.result;
  return ok({
    spec: m,
    error: o?.error,
    dependsOn: o?.dependsOn,
    result: res && {
      callout: res.callout,
      pass: res.pass,
      governing: res.governing,
      checks: res.checks,
      reactions: res.reactions,
      flags: res.flags,
      assumptions: res.assumptions,
      alternatives: res.alternatives
    }
  });
});
tool("add_member", {
  description: "Add a member from the app's template for kind (joist, rafter, ceilingJoist, ijoist, beam, header, ridge, truss, wall, post, connector, footing, pad, shearWall, ftaoWall, roofDiaphragm, floorDiaphragm, transfer, uplift, ledger, steelBeam, steelColumn, basePlate, cmuWall, concreteWall, holdownFooting, tieIn, woodTruss, retainingWall, guardPost, cfsWall). Mark is assigned from the project's mark scheme; optional patch is merged onto the template (objects merge, arrays replace).",
  inputSchema: {
    kind: stringType2(),
    structureId: stringType2().optional(),
    levelId: stringType2().optional(),
    patch: recordType2(stringType2(), unknownType2()).optional()
  }
}, async ({ kind, structureId, levelId, patch }) => {
  const s = project.structures.find((x) => x.id === structureId) ?? project.structures[0];
  const lvl = levelId ?? s.levels[0].id;
  let spec;
  try {
    spec = newMemberSpec(project, kind, s.id, lvl);
  } catch (e) {
    return fail(`Cannot create '${kind}': ${e instanceof Error ? e.message : String(e)}`);
  }
  const merged = merge2(spec, patch ?? {});
  const errs = commit({ ...project, members: [...project.members, merged] });
  if (errs)
    return fail(`Rejected:
${errs.join(`
`)}`);
  return ok({ added: findMember(merged.id) });
});
tool("update_member", {
  description: "Change a member (by id or mark): patch is merged onto its spec (objects merge, arrays replace, null deletes). Rejected if the project no longer validates.",
  inputSchema: { member: stringType2(), patch: recordType2(stringType2(), unknownType2()) }
}, async ({ member, patch }) => {
  const m = findMember(member);
  if (!m)
    return fail(`No member '${member}'.`);
  const next = merge2(m, { ...patch, id: m.id, kind: m.kind });
  const errs = commit({ ...project, members: project.members.map((x) => x.id === m.id ? next : x) });
  if (errs)
    return fail(`Rejected:
${errs.join(`
`)}`);
  return ok({ updated: findMember(m.id) });
});
tool("delete_member", {
  description: "Remove a member (by id or mark). Load-path links from other members to it are reported, not removed.",
  inputSchema: { member: stringType2() }
}, async ({ member }) => {
  const m = findMember(member);
  if (!m)
    return fail(`No member '${member}'.`);
  project = { ...project, members: project.members.filter((x) => x.id !== m.id) };
  const linkedFrom = project.members.filter((x) => x.links.some((l) => l.sourceId === m.id)).map((x) => x.mark);
  return ok({ deleted: m.mark, stillLinkedFrom: linkedFrom });
});
tool("update_project", {
  description: "Change project-level data (info, criteria, assemblies, structures, marks, hardware, lateral, notes, slab, ...): patch merged onto the project (objects merge, arrays replace). Use add/update_member for members.",
  inputSchema: { patch: recordType2(stringType2(), unknownType2()) }
}, async ({ patch }) => {
  const { members: _ignored, ...rest } = patch;
  const errs = commit(merge2(project, rest));
  if (errs)
    return fail(`Rejected:
${errs.join(`
`)}`);
  return ok({ info: project.info, criteria: project.criteria });
});
tool("fill_from_markdown", {
  description: "Fill the project from a HouseCalc Markdown input sheet (same as the app's 'Fill from .md…'). Give text or a path. mode 'fill' updates the current project, 'new' starts a fresh one. Use export_markdown on the example for the format.",
  inputSchema: {
    text: stringType2().optional(),
    path: stringType2().optional(),
    mode: enumType2(["fill", "new"]).default("fill")
  }
}, async ({ text, path, mode }) => {
  const md = text ?? (path ? await readFile(resolve(path), "utf8") : undefined);
  if (!md)
    return fail("Pass text or path.");
  const r = applyMarkdown(project, md, { mode });
  if (!r.ok)
    return fail(`Nothing applied:
${JSON.stringify(r.report, null, 2)}`);
  project = r.project;
  return ok({ ...r.report, members: project.members.length });
});
tool("export_markdown", {
  description: "The project as a HouseCalc Markdown input sheet (same as the app's 'Export .md'); written to path if given, else returned.",
  inputSchema: { path: stringType2().optional() }
}, async ({ path }) => {
  const md = projectToMarkdown(project);
  if (!path)
    return { content: [{ type: "text", text: md }] };
  await writeFile(resolve(path), md);
  return ok({ saved: resolve(path) });
});
tool("run_design", {
  description: "Design every member through the load path and return the package checks (marks, errors, failures, uncarried reactions, untied uplift, verify items), lateral status and each member's callout, status and governing D/C.",
  inputSchema: {}
}, async () => {
  const { d, rows } = memberRows();
  return ok({
    packageChecks: packageChecks(project, d),
    validation: validationItems(project, d),
    circular: d.circular.map((id) => findMember(id)?.mark ?? id),
    lateralError: d.lateralError,
    members: rows
  });
});
await server.connect(new StdioServerTransport);
console.error("housecalc MCP server ready");
